    public static function chave(string $pt): string
    {
        return self::GRUPO . '.t' . substr(md5($pt), 0, 10);
    }

    public static function t(string $pt, array $valores = []): string
    {
        $r = $pt;
        if (isset(self::TR[$pt])) {
            [$en, $es] = self::TR[$pt];
            $r = IdiomaService::t(self::chave($pt), ['pt' => $pt, 'en' => $en, 'es' => $es]);
            // O banco guarda o texto sem os espaços das pontas: devolve os espaços do original (pedaços de frase, ex.: ' (fora do menu)')
            preg_match('/^\s*/u', $pt, $ini); preg_match('/\s*$/u', $pt, $fim);
            $r = ($ini[0] ?? '') . trim($r) . ($fim[0] ?? '');
        }
        foreach ($valores as $k => $v) $r = str_replace('{' . $k . '}', (string)$v, $r);
        return $r;
    }

    public static function traduzivel(string $pt): bool
    {
        return isset(self::TR[$pt]) && IdiomaService::idioma() !== 'pt';
    }

    /** Dicionário dos textos do JavaScript no idioma atual (window.greenTxt). */
    public static function script(): string
    {
        $mapa = [];
        if (IdiomaService::idioma() !== 'pt') foreach (self::JS as $pt) { $t = self::t($pt); if ($t !== $pt) $mapa[$pt] = $t; }
        $json = json_encode((object)$mapa, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?: '{}';
        return '<script>window.greenTxtMapa=Object.assign(window.greenTxtMapa||{},' . $json . ');'
            . 'window.greenTxt=window.greenTxt||function(s){var v=window.greenTxtMapa&&window.greenTxtMapa[s];return typeof v==="string"&&v!==""?v:s;};</script>';
    }

    /** Itens para registrar no banco (scripts/aplicar-onda3-idiomas.php). */
    public static function itensIdioma(): array
    {
        $itens = []; $o = 0;
        foreach (self::TR as $pt => [$en, $es]) $itens[] = ['chave' => self::chave($pt), 'tipo' => 'ROTULO', 'ordem' => ++$o, 'descricao' => 'Administração, Segurança e Setup', 'pt' => $pt, 'en' => $en, 'es' => $es];
        return $itens;
    }
}

if (!function_exists('adm_t')) {
    function adm_t(string $pt, array $valores = []): string { return AdministracaoTextos::t($pt, $valores); }
    function adm_h(string $pt): string { return AdministracaoTextos::t($pt); }
    function adm_a(string $pt): string { return AdministracaoTextos::traduzivel($pt) ? htmlspecialchars(AdministracaoTextos::t($pt), ENT_QUOTES, 'UTF-8') : $pt; }
    function adm_js(string $pt): string { return json_encode(AdministracaoTextos::t($pt), JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?: '""'; }
}
